ncmModules['/playlist/tracks'] = async (query, request) => {
  //
  const tracks = query.tracks.split(',');
  const data = {
    op: query.op, // del,add
    pid: query.pid, // 歌单id
    trackIds: JSON.stringify(tracks), // 歌曲id
    imme: 'true'
  };

  try {
    const res = await request(`/api/playlist/manipulate/tracks`, data, createOption(query));
    return {
      status: 200,
      body: {
        ...res
      }
    };
  } catch (error) {
    if (error.body.code === 512) {
      return request(
        `/api/playlist/manipulate/tracks`,
        {
          op: query.op, // del,add
          pid: query.pid, // 歌单id
          trackIds: JSON.stringify([...tracks, ...tracks]),
          imme: 'true'
        },
        createOption(query)
      );
    } else {
      return {
        status: 200,
        body: error.body
      };
    }
  }
};
